 body.innerHTML=`<div class="tank-process-status"><span class="tank-process-vessel">${esc(tank.container_type||'tank')} · ${processValue(tank.volume_l,' L')} / ${processValue(tank.capacity_l,' L')}</span><span class="sensor-live ${p?.connected?'connected':'fault'}">${p?'Tank Sensor '+(p.connected?'live':'stale'):'recorded data'}</span></div>${facts}${p?fermentationDigitalTwin(history,projection,p.final_gravity,p.history_sample_count):''}${projectionBlock}${tankLaboratoryEvidenceMarkup(tank,history,projection)}${fermentationEventRail(projection,labEvidence)}${tankWineHistoryMarkup(tank)}${p?`<section class="fermentation-graphs"><div class="chart-heading fermentation-detail-heading"><div><h3>Measured detail views</h3><span>Original sensor-resolution series remain available</span></div></div>${fermentationChart(history,'density_sg','Specific gravity',' SG','#b58a25',p.final_gravity)}${fermentationChart(history,'temperature_c','Temperature','°C','#b85b45',null)}</section>`:''}${sensorHealth}<section><div class="chart-heading"><div><h3>Complete Tank Sensor process</h3><span>Wine process record · ${process.length} linked cellar observation${process.length===1?'':'s'}</span></div></div><ol class="fermentation-timeline">${timeline}</ol></section>${readings}`;
