  chains.querySelectorAll('.damage-event-chain').forEach((card,index)=>{const eventDate=chainRows[index]?.event_date,meta=card.querySelector('summary small');if(eventDate&&meta)meta.prepend(document.createTextNode(`Occurred ${new Date(String(eventDate).slice(0,10)+'T12:00:00').toLocaleDateString()} · `))});
